package cn.mop.api;

import cn.mop.domain.DomainException;
import cn.mop.domain.notification.DeliveryReceiptState;
import cn.mop.domain.notification.DeliveryReceiptState.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Isolated explicit receipt inputs, not provider delivery, callback authentication or database evidence. */
class DeliveryReceiptStateTest {
    final UUID tenant=UUID.randomUUID(), delivery=UUID.randomUUID(), request=UUID.randomUUID();
    final Instant t=Instant.parse("2026-10-04T00:00:00Z");
    final Deduplication key=new Deduplication(UUID.randomUUID(),UUID.randomUUID(),Channel.SMS,UUID.randomUUID(),"INITIAL");
    DeliveryReceiptState queued(){return DeliveryReceiptState.queued(tenant,delivery,key,t);}
    DeliveryReceiptState running(){return queued().start(0,request,t);}
    Receipt receipt(UUID req,ReceiptStatus status,long seconds){return new Receipt(tenant,delivery,req,UUID.randomUUID(),status,t.plusSeconds(seconds));}
    DeliveryReceiptState failed(){return running().record(1,receipt(request,ReceiptStatus.FAILED,1),t.plusSeconds(2));}
    DeliveryReceiptState dead(){return failed().deadLetter(2,t.plusSeconds(3));}
    @Test void queuedAndUnknownAreNotDelivered(){assertEquals(Status.QUEUED,queued().status());assertEquals(Status.UNKNOWN,running().status());assertEquals(0,running().logicalDeliveredCount());assertNull(running().firstDeliveredAt());}
    @Test void acceptedDoesNotMeanDelivered(){var r=running().record(1,receipt(request,ReceiptStatus.ACCEPTED,1),t.plusSeconds(2));assertEquals(Status.ACCEPTED,r.status());assertEquals(0,r.logicalDeliveredCount());assertNull(r.firstDeliveredAt());}
    @Test void deliveredRequiresExplicitReceiptAndCountsOneLogicalDelivery(){var r=running().record(1,receipt(request,ReceiptStatus.DELIVERED,1),t.plusSeconds(2));assertEquals(Status.DELIVERED,r.status());assertEquals(1,r.logicalDeliveredCount());assertEquals(t.plusSeconds(1),r.firstDeliveredAt());}
    @Test void exactReceiptReplayIsNoOpEvenWithStaleVersion(){var receipt=receipt(request,ReceiptStatus.ACCEPTED,1);var r=running().record(1,receipt,t.plusSeconds(2));assertSame(r,r.record(1,receipt,t.plusSeconds(3)));assertEquals(2,r.version());assertEquals(1,r.receipts().size());}
    @Test void sameReceiptIdentityWithDifferentFactsConflicts(){var old=receipt(request,ReceiptStatus.ACCEPTED,1);var r=running().record(1,old,t.plusSeconds(2));var changed=new Receipt(tenant,delivery,request,old.receiptId(),ReceiptStatus.DELIVERED,old.occurredAt());assertEquals(409,assertThrows(DomainException.class,()->r.record(2,changed,t.plusSeconds(3))).status);}
    @Test void crossTenantAndCrossDeliveryReceiptsAre404BeforeVersionCheck(){for(var bad:List.of(new Receipt(UUID.randomUUID(),delivery,request,UUID.randomUUID(),ReceiptStatus.DELIVERED,t),new Receipt(tenant,UUID.randomUUID(),request,UUID.randomUUID(),ReceiptStatus.DELIVERED,t)))assertEquals(404,assertThrows(DomainException.class,()->running().record(99,bad,t)).status);}
    @Test void unmatchedRequestIsRejected(){assertEquals(400,assertThrows(DomainException.class,()->running().record(1,receipt(UUID.randomUUID(),ReceiptStatus.DELIVERED,0),t)).status);}
    @Test void futureOrPreRequestReceiptCannotBeRecorded(){var r=queued().start(0,request,t.plusSeconds(2));for(var bad:List.of(receipt(request,ReceiptStatus.DELIVERED,1),receipt(request,ReceiptStatus.DELIVERED,4)))assertThrows(DomainException.class,()->r.record(1,bad,t.plusSeconds(3)));}
    @Test void repeatedStartsWhileUnknownAcceptedOrFailedAreRejected(){var accepted=running().record(1,receipt(request,ReceiptStatus.ACCEPTED,1),t.plusSeconds(2));for(var r:List.of(running(),accepted,failed()))assertThrows(DomainException.class,()->r.start(r.version(),UUID.randomUUID(),t.plusSeconds(3)));}
    @Test void deadLetterRequiresExplicitFailureNotUnknownOrAccepted(){var accepted=running().record(1,receipt(request,ReceiptStatus.ACCEPTED,1),t.plusSeconds(2));for(var r:List.of(queued(),running(),accepted))assertThrows(DomainException.class,()->r.deadLetter(r.version(),t.plusSeconds(3)));assertEquals(Status.DEAD_LETTER,dead().status());}
    @Test void replayRetainsDeduplicationAndRequiresNewRequestIdentity(){var d=dead();assertThrows(DomainException.class,()->d.start(3,request,t.plusSeconds(4)));var next=d.start(3,UUID.randomUUID(),t.plusSeconds(4));assertEquals(key,next.deduplication());assertEquals(delivery,next.deliveryId());assertEquals(2,next.attempts().size());assertEquals(1,next.receipts().size());assertEquals(Status.UNKNOWN,next.status());}
    @Test void lateFailedOrAcceptedEarlierAttemptCannotChangeCurrentAttempt(){var r=dead().start(3,UUID.randomUUID(),t.plusSeconds(4));r=r.record(4,receipt(request,ReceiptStatus.ACCEPTED,1),t.plusSeconds(5));assertEquals(Status.UNKNOWN,r.status());r=r.record(5,receipt(request,ReceiptStatus.FAILED,2),t.plusSeconds(6));assertEquals(Status.UNKNOWN,r.status());}
    @Test void lateDeliveredEarlierAttemptStopsFutureReplayAndCountsOnce(){var nextId=UUID.randomUUID();var r=dead().start(3,nextId,t.plusSeconds(4));r=r.record(4,receipt(request,ReceiptStatus.DELIVERED,2),t.plusSeconds(5));r=r.record(5,receipt(nextId,ReceiptStatus.DELIVERED,5),t.plusSeconds(6));assertEquals(1,r.logicalDeliveredCount());assertEquals(t.plusSeconds(2),r.firstDeliveredAt());var finalState=r;assertThrows(DomainException.class,()->finalState.start(finalState.version(),UUID.randomUUID(),t.plusSeconds(7)));}
    @Test void lateAcceptanceNeverDowngradesFailure(){var r=failed().record(2,receipt(request,ReceiptStatus.ACCEPTED,0),t.plusSeconds(3));assertEquals(Status.FAILED,r.status());assertEquals(2,r.receipts().size());}
    @Test void lateFailureNeverDowngradesDelivery(){var r=running().record(1,receipt(request,ReceiptStatus.DELIVERED,1),t.plusSeconds(2)).record(2,receipt(request,ReceiptStatus.FAILED,2),t.plusSeconds(3));assertEquals(Status.DELIVERED,r.status());assertEquals(2,r.receipts().size());}
    @Test void deliveredAfterDeadLetterReconcilesWithoutNewAttempt(){var r=dead().record(3,receipt(request,ReceiptStatus.DELIVERED,1),t.plusSeconds(4));assertEquals(Status.DELIVERED,r.status());assertEquals(1,r.attempts().size());}
    @Test void staleVersionsAndRegressingObservationTimesAreRejected(){var r=running();assertEquals("VERSION_CONFLICT",assertThrows(DomainException.class,()->r.record(0,receipt(request,ReceiptStatus.ACCEPTED,0),t)).code);assertThrows(DomainException.class,()->r.record(1,receipt(request,ReceiptStatus.ACCEPTED,0),t.minusNanos(1)));}
    @Test void historySnapshotsAndListsRemainImmutable(){var q=queued();var r=q.start(0,request,t);var accepted=r.record(1,receipt(request,ReceiptStatus.ACCEPTED,1),t.plusSeconds(2));assertEquals(Status.QUEUED,q.status());assertEquals(Status.UNKNOWN,r.status());assertThrows(UnsupportedOperationException.class,()->accepted.attempts().clear());assertThrows(UnsupportedOperationException.class,()->accepted.receipts().clear());}
    @Test void nanosecondFactsAreNotRoundedAway(){var precise=t.plusNanos(1);var x=new Receipt(tenant,delivery,request,UUID.randomUUID(),ReceiptStatus.DELIVERED,precise);assertEquals(precise,running().record(1,x,t.plusNanos(2)).firstDeliveredAt());}
    @Test void invalidInputIsRejectedWithoutEchoingSensitiveStrings(){var e=assertThrows(DomainException.class,()->new Deduplication(tenant,delivery,Channel.EMAIL,request,"SYNTHETIC-SECRET"));assertFalse(e.getMessage().contains("SYNTHETIC"));assertThrows(DomainException.class,()->queued().start(0,null,t));assertThrows(DomainException.class,()->DeliveryReceiptState.queued(null,delivery,key,t));assertThrows(DomainException.class,()->new Attempt(request,Instant.MAX));assertThrows(DomainException.class,()->running().record(1,null,t));}
    @Test void customerPoliciesAndSendingRemainUnresolved(){for(var r:List.of(queued(),running(),failed(),dead())){assertFalse(r.providerReceiptVerified());assertFalse(r.automaticSendEnabled());assertNull(r.effectiveRetryBudget());assertNull(r.effectiveSmsQuota());assertEquals("EXPLICIT_RECEIPT_STATE_ONLY",r.scope());}}
    @Test void allReceiptOrdersRetainDeliveryWithoutDuplicatingLogicalCount(){var values=List.of(receipt(request,ReceiptStatus.ACCEPTED,0),receipt(request,ReceiptStatus.FAILED,1),receipt(request,ReceiptStatus.DELIVERED,2));for(int a=0;a<3;a++)for(int b=0;b<3;b++)for(int c=0;c<3;c++){if(a==b||b==c||a==c)continue;var r=running();for(int index:new int[]{a,b,c})r=r.record(r.version(),values.get(index),t.plusSeconds(3));assertEquals(Status.DELIVERED,r.status());assertEquals(1,r.logicalDeliveredCount());assertEquals(3,r.receipts().size());}}
    @Test void attemptTechnicalLimitRejectsWithoutChangingHistory(){var r=queued();for(int i=0;i<DeliveryReceiptState.MAX_ATTEMPTS;i++){UUID id=UUID.randomUUID();r=r.start(r.version(),id,t);r=r.record(r.version(),receipt(id,ReceiptStatus.FAILED,0),t);r=r.deadLetter(r.version(),t);}var full=r;assertEquals(1000,full.attempts().size());assertThrows(DomainException.class,()->full.start(full.version(),UUID.randomUUID(),t));assertEquals(Status.DEAD_LETTER,full.status());assertNull(full.effectiveRetryBudget());}
    @Test void receiptTechnicalLimitAllowsExactReplayButRejectsAdditionalFacts(){var r=running();Receipt first=null;for(int i=0;i<DeliveryReceiptState.MAX_RECEIPTS;i++){Receipt value=receipt(request,ReceiptStatus.ACCEPTED,0);if(first==null)first=value;r=r.record(r.version(),value,t);}var full=r;assertEquals(10000,full.receipts().size());assertSame(full,full.record(0,first,t));assertThrows(DomainException.class,()->full.record(full.version(),receipt(request,ReceiptStatus.ACCEPTED,0),t));assertEquals(Status.ACCEPTED,full.status());assertEquals(0,full.logicalDeliveredCount());}

}
